		decStr = decStr:gsub(LUAOBFUSACTOR_DECRYPT_STR_0("\238\187\95", "\95\222\144\123\97\55\16"), "");
		if (decStr ~= ".") then
			return sign .. formatted .. decStr;
		end
	end
