Hub.DecodeSkinEnum = function(self, raw)
	local group, item = string.match(raw, LUAOBFUSACTOR_DECRYPT_STR_0("\211\250\215\53\224\154\151\104\214\154\206\31\208\148\144\101\163\151\226\101\250\224\228\107\164\155", "\64\141\191\185"));
	if not group then
		return nil;
	end
	local ok, val = pcall(function()
		return Enum[group][item];
	end);
	return (ok and val) or nil;
end;
Hub.DecodeSkinProperty = function(self, current, raw)
	local k = type(raw);
	if ((k == "number") or (k == "boolean")) then
		return raw;
	end
	local want = typeof(current);
	if (k == "string") then
		if (want == "EnumItem") then
			return self:DecodeSkinEnum(raw);
		end
		return raw;
	end
	if (k ~= "table") then
		return nil;
	end
	if (want == LUAOBFUSACTOR_DECRYPT_STR_0("\53\239\179\206\248\219\245", "\198\99\138\208\186\151\169")) then
		return Vector3.new(raw[1], raw[2], raw[3]);
	elseif (want == "Vector2") then
		return Vector2.new(raw[1], raw[2]);
	elseif (want == LUAOBFUSACTOR_DECRYPT_STR_0("\46\250\143\81\31\166", "\62\109\149\227")) then
		return Color3.new(raw[1], raw[2], raw[3]);
	elseif (want == "NumberRange") then
		return NumberRange.new(raw[1], raw[2]);
	elseif (want == "CFrame") then
		return CFrame.new(table.unpack(raw));
	elseif (want == LUAOBFUSACTOR_DECRYPT_STR_0("\221\157\132\214\5\225\187\140\197\21\246\134\138\209", "\96\147\232\233\180")) then
		local keys = {};
		for i = 1, #raw do
			local pt = raw[i];
			keys[i] = NumberSequenceKeypoint.new(pt.t, pt.v, pt.e or 0);
		end
		if (#keys < 2) then
			return NumberSequence.new((keys[1] and keys[1].Value) or 0);
		end
		return NumberSequence.new(keys);
	elseif (want == LUAOBFUSACTOR_DECRYPT_STR_0("\11\55\22\68\159\10\45\41\15\78\131\58\45", "\89\72\88\122\43\237")) then
		local keys = {};
		for i = 1, #raw do
			local pt = raw[i];
			local rgb = pt.c;
			keys[i] = ColorSequenceKeypoint.new(pt.t, Color3.new(rgb[1], rgb[2], rgb[3]));
		end
		if (#keys < 2) then
			return ColorSequence.new((keys[1] and keys[1].Value) or Color3.new(1, 1, 1));
		end
		return ColorSequence.new(keys);
	end
	return nil;
end;
Hub.ApplySkinProps = function(self, inst, props)
	if (type(props) ~= "table") then
		return inst;
	end
	for key, raw in pairs(props) do
		if not skinPropNope[key] then
			local ok, curr = pcall(function()
				return inst[key];
			end);
			if ok then
				local val = self:DecodeSkinProperty(curr, raw);
				if (val ~= nil) then
					pcall(function()
						inst[key] = val;
					end);
				end
			end
		end
	end
	return inst;
end;
Hub.RegisterSkinGarbage = function(self, owner, inst)
	if (not owner or not inst) then
		return inst;
	end
	local list = self.SkinSystem.Musor[owner];
	if not list then
		list = {};
		self.SkinSystem.Musor[owner] = list;
	end
	list[#list + 1] = inst;
	return inst;
end;
Hub.ClearSkinGarbage = function(self, owner)
	local list = self.SkinSystem.Musor[owner];
	if not list then
		return;
	end
	for i = #list, 1, -1 do
		local inst = list[i];
		if inst then
			pcall(function()
				inst:Destroy();
			end);
		end
		list[i] = nil;
	end
end;
Hub.BackupSkinProp = function(self, inst, data)
	if not inst then
		return;
