Hub.ResolveAnimationId = function(self, assetId)
	local rawId = tostring(assetId);
	local ok, objs = pcall(game.GetObjects, game, "rbxassetid://" .. rawId);
	if (ok and objs and (#objs > 0)) then
		for _, obj in ipairs(objs) do
			if (obj:IsA("Animation") and (obj.AnimationId ~= "")) then
				return obj.AnimationId;
			end
			local found = obj:FindFirstChildWhichIsA(LUAOBFUSACTOR_DECRYPT_STR_0("\140\59\68\83\172\33\68\81\163", "\62\205\85\45"), true);
			if (found and (found.AnimationId ~= "")) then
				return found.AnimationId;
			end
		end
	end
	return LUAOBFUSACTOR_DECRYPT_STR_0("\103\14\185\168\17\154\12\97\5\165\243\77\198", "\105\21\108\193\201\98\233") .. rawId;
end;
